def handle(args, state, ds):
    detail = ds.sync_status()
    if detail.get("drift") is False:
        return {"status": "synced", "detail": "all linked accounts up to date"}
    return {"status": "syncing", "detail": detail.get("accounts_in_progress", [])}

def handle(args, state, ds):
    report = ds.consistency_report()
    if report.get("pending", 0) == 0:
        return {"status": "complete", "remaining": 0}
    return {"status": "in_progress", "remaining": report.get("pending", 0)}

def handle(args, state, ds):
    report = ds.consistency_report()
    if report.get("pending", 0) == 0 and report.get("checked", 0) > 0:
        return {"status": "complete", "remaining": 0}
    return {"status": "in_progress", "remaining": report.get("pending", 0)}
